import { not } from 'fp-ts-esm/Predicate';

import { and } from './../ricos-content/index.js';
import { extract } from './../ricos-content/lib/extract.js';
import { modify } from './../ricos-content/lib/modify.js';
import type { Node } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';

import { ANCHORABLE_PLUGIN_NODES, ANCHORABLE_TEXT_NODES } from './constants.js';

const isAnchorableAtomicPluginNode = (node: Node): boolean =>
  ANCHORABLE_PLUGIN_NODES.includes(node.type as any);

const isAnchorableTextNode = (node: Node): boolean =>
  ANCHORABLE_TEXT_NODES.includes(node.type as any);

const isAnchorableNode = (node: Node): boolean => {
  return isAnchorableAtomicPluginNode(node) || isAnchorableTextNode(node);
};

const isEmptyImageNode = ({ imageData, type }: Node): boolean =>
  type === Node_Type.IMAGE && !(imageData?.image?.src?.id || imageData?.image?.src?.url);

const isEmptyTextNode = (node: Node): boolean =>
  isAnchorableTextNode(node) &&
  (!node.nodes ||
    node.nodes.length === 0 ||
    (node.type === Node_Type.BLOCKQUOTE &&
      (!node.nodes[0]?.nodes || node.nodes[0]?.nodes.length === 0)));

const isSelectedNode =
  (selectedNodeId: string) =>
  (node: Node): boolean => {
    const { id } = node;
    return selectedNodeId === id;
  };

const handleBlockquoteTextData = (nodes: Node[]) => {
  return modify({ nodes })
    .filter(node => node.type === Node_Type.BLOCKQUOTE)
    .set(node => {
      const nodes = node.nodes;
      if (!nodes?.length) {
        return node;
      }
      nodes[0].textData = nodes[0]?.nodes?.[0]?.textData;
      return {
        ...node,
        nodes,
      };
    }).nodes;
};

export const getAnchorableNodesQuery = (
  contentExtractor: ReturnType<typeof extract>,
  selectedNodeId: $TSFixMe
): Node[] => {
  const anchorableNodes: Node[] = contentExtractor
    .filter(
      and([
        // @ts-ignore $TSFixMe
        isAnchorableNode,
        // @ts-ignore $TSFixMe
        not(isEmptyImageNode),
        // @ts-ignore $TSFixMe
        not(isEmptyTextNode),
        // @ts-ignore $TSFixMe
        not(isSelectedNode(selectedNodeId)),
      ])
    )
    .get();

  const paragraphIdsToCleanup = extract(anchorableNodes)
    .filter(node => anchorableNodes.some(n => node.id === n.nodes?.[0]?.id))
    .map(node => node.id)
    .get();

  const anchorableNodesWithoutDuplications = anchorableNodes.filter(
    node => !(paragraphIdsToCleanup.includes(node.id) && node.type === Node_Type.PARAGRAPH)
  );

  const finalAnchorableNodes = handleBlockquoteTextData(anchorableNodesWithoutDuplications);

  return finalAnchorableNodes ?? [];
};
